with (D/'publication.json').open('x') as f:json.dump(dict(all_passed=True,scope='Corrected GREEN scoped correctness accepted; no performance/public integration/promotion',exact_names=NAMES,staged_blobs_excluding_self=blobs,sha256={n:sha(R/n) for n in other},self_binding='Exact staged and committed set; self blob verified after commit'),f,indent=2);f.write('\n')
